<?php /** @var bool $compact */ ?>
<?php if($companies===[]):?><div class="ai-platform__empty">등록된 회사가 없습니다.</div><?php else:?><div class="table-responsive"><table class="table align-middle" data-platform-table><thead><tr><th>회사</th><th>요금제</th><th>고객 사용량</th><th>회원</th><th>기기</th><?php if(!$compact):?><th>상태</th><th>가입일</th><?php endif;?></tr></thead><tbody><?php foreach($companies as $company):?><tr><td><strong><?=htmlspecialchars((string)$company['name'])?></strong><small class="d-block text-muted"><?=htmlspecialchars((string)$company['slug'])?> · <span class="ai-platform__mono"><?=htmlspecialchars($short((string)$company['company_id']))?></span></small></td><td><?=htmlspecialchars((string)($company['plan_name']??$company['plan_code']??'-'))?></td><td><?=number_format((int)$company['customer_count'])?> / <?=number_format((int)($company['customer_limit']??0))?>명</td><td><?=number_format((int)$company['user_count'])?>명</td><td><?=number_format((int)$company['device_count'])?>대</td><?php if(!$compact):?><td><span class="badge text-bg-<?=$badge((string)$company['status'])?>"><?=htmlspecialchars($statusLabels[(string)$company['status']]??(string)$company['status'])?></span></td><td class="text-muted"><?=$date((string)$company['created_at'])?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php endif;?>
